validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  // Server admin or db admin can do anything
  if (userCtx.roles.indexOf('_admin') !== -1 || userCtx.roles.indexOf('admin') !== -1) return;

  // Deletions — admin only
  if (newDoc._deleted) {
    throw({forbidden: 'Only admins can delete documents'});
  }

  // User docs — users can edit their own
  if (newDoc._id.indexOf('org.couchdb.user:') === 0) {
    var docUser = newDoc.name;
    if (userCtx.name !== docUser) {
      throw({forbidden: 'You can only edit your own user document'});
    }
    // Non-admins cannot change roles or type
    if (oldDoc) {
      if (JSON.stringify(newDoc.roles) !== JSON.stringify(oldDoc.roles)) {
        throw({forbidden: 'Only admins can change roles'});
      }
      if (newDoc.type !== oldDoc.type) {
        throw({forbidden: 'Only admins can change document type'});
      }
    }
    // Required fields
    if (!newDoc.name || !newDoc.type || newDoc.type !== 'user') {
      throw({forbidden: 'User documents must have name and type=user'});
    }
    return;
  }

  // Everything else (domains, aliases, invites, design docs) — admin only
  throw({forbidden: 'Only admins can modify this document'});
}
